import { expect, type Page, test } from "@playwright/test";

import { login, openProfileSubmenu, signOut } from "./helpers/auth";
import { adminClient, createUser, emailLink, TEST_PASSWORD, testEmail } from "./helpers/supabase-admin";

// Authentication journeys (docs/auth.md). No test sends an email: links are generated by the
// Supabase admin API. The Google button is checked by hand.

async function sessionCookies(page: Page) {
  return (await page.context().cookies()).filter((cookie) => cookie.name.startsWith("sb-"));
}

test.describe("page access", () => {
  test("a signed-out visitor is sent to the login page, then back to the page asked for", async ({ page }) => {
    const user = await createUser();
    await page.goto("/app/profile");
    await expect(page).toHaveURL(/\/login\?next=%2Fapp%2Fprofile$/);

    await login(page, user.email, user.password);
    await expect(page).toHaveURL(/\/app\/profile$/);
    await expect(page.getByRole("heading", { name: "Mon profil" })).toBeVisible();
  });

  test("the site address leads to the login page", async ({ page }) => {
    await page.goto("/");
    await expect(page).toHaveURL(/\/login$/);
    await expect(page.getByRole("heading", { name: "Connexion" })).toBeVisible();
  });

  test("a signed-in visitor is sent from login and sign-up to the app", async ({ page }) => {
    const user = await createUser();
    await page.goto("/login");
    await login(page, user.email, user.password);
    await expect(page).toHaveURL(/\/app$/);

    await page.goto("/login");
    await expect(page).toHaveURL(/\/app$/);
    await page.goto("/signup");
    await expect(page).toHaveURL(/\/app$/);
  });
});

test.describe("login and logout", () => {
  test("logs in, shows the account in the sidebar, logs out", async ({ page }) => {
    const user = await createUser();
    await page.goto("/login");
    await login(page, user.email, user.password);

    await expect(page).toHaveURL(/\/app$/);
    const profileButton = page.getByRole("button", { name: "Menu du profil" });
    await expect(profileButton).toContainText(user.email);
    // No Google photo: the avatar shows the initial of the address.
    await expect(profileButton).toContainText("E");

    await signOut(page);
    await page.goto("/app/profile");
    await expect(page).toHaveURL(/\/login\?next=%2Fapp%2Fprofile$/);
  });

  test("lands on the dashboard, then the sidebar leads to Mon profil", async ({ page }) => {
    const user = await createUser();
    await page.goto("/login");
    await login(page, user.email, user.password);

    await expect(page).toHaveURL(/\/app$/);
    await expect(page.getByRole("heading", { name: "Tableau de bord" })).toBeVisible();
    const nav = page.getByRole("navigation", { name: "Navigation principale" });
    await expect(nav.getByRole("link", { name: "Tableau de bord" })).toHaveAttribute("aria-current", "page");

    await nav.getByRole("link", { name: "Mon profil" }).click();
    await expect(page).toHaveURL(/\/app\/profile$/);
    await expect(page.getByRole("heading", { name: "Mon profil" })).toBeVisible();
    await expect(nav.getByRole("link", { name: "Mon profil" })).toHaveAttribute("aria-current", "page");
    await expect(nav.getByRole("link", { name: "Tableau de bord" })).not.toHaveAttribute("aria-current");
  });

  test("the profile menu changes the theme", async ({ page }) => {
    const user = await createUser();
    await page.goto("/login");
    await login(page, user.email, user.password);
    await expect(page).toHaveURL(/\/app$/);

    await openProfileSubmenu(page, "Thème");
    await page.getByRole("menuitemradio", { name: "Sombre" }).click();
    await expect(page.locator("html")).toHaveClass(/dark/);
    await page.getByRole("menuitemradio", { name: "Clair" }).click();
    await expect(page.locator("html")).not.toHaveClass(/dark/);
  });
});

test.describe("login errors", () => {
  test("empty fields", async ({ page }) => {
    await page.goto("/login");
    await page.getByRole("button", { name: "Se connecter" }).click();
    await expect(page.getByText("Indiquez votre adresse e-mail.")).toBeVisible();
    await expect(page.getByText("Indiquez votre mot de passe.")).toBeVisible();
  });

  test("wrong password and unknown account get the same message", async ({ page }) => {
    const user = await createUser();
    await page.goto("/login");
    await login(page, user.email, "not-the-password");
    await expect(page.locator("main").getByRole("alert")).toHaveText("E-mail ou mot de passe incorrect.");

    await login(page, testEmail(), "whatever-password");
    await expect(page.locator("main").getByRole("alert")).toHaveText("E-mail ou mot de passe incorrect.");
    await expect(page).toHaveURL(/\/login$/);
  });

  test("an unconfirmed address is told so, with a button to resend the email", async ({ page }) => {
    const user = await createUser({ confirmed: false });
    await page.goto("/login");
    await login(page, user.email, user.password);
    await expect(page.locator("main").getByRole("alert")).toContainText("pas encore confirmée");
    // Not clicked: it would send a real email.
    await expect(page.getByRole("button", { name: "Renvoyer l'e-mail" })).toBeVisible();
  });
});

test.describe("Rester connecté", () => {
  test("checked: the session survives the browser closing", async ({ page }) => {
    const user = await createUser();
    await page.goto("/login");
    await login(page, user.email, user.password);
    await expect(page).toHaveURL(/\/app$/);

    const cookies = await sessionCookies(page);
    expect(cookies.length).toBeGreaterThan(0);
    const inOneYear = Date.now() / 1000 + 365 * 24 * 60 * 60;
    for (const cookie of cookies) expect(cookie.expires).toBeGreaterThan(inOneYear);
  });

  test("unchecked: the session ends with the browser", async ({ page }) => {
    const user = await createUser();
    await page.goto("/login");
    await login(page, user.email, user.password, { remember: false });
    await expect(page).toHaveURL(/\/app$/);

    const cookies = await sessionCookies(page);
    expect(cookies.length).toBeGreaterThan(0);
    // -1: a session cookie, deleted when the browser closes.
    for (const cookie of cookies) expect(cookie.expires).toBe(-1);

    // The choice also holds when the session is refreshed on later pages.
    await page.reload();
    for (const cookie of await sessionCookies(page)) expect(cookie.expires).toBe(-1);
  });
});

test.describe("sign-up", () => {
  test("the form checks the password length (without sending anything)", async ({ page }) => {
    await page.goto("/signup");
    await expect(page.getByRole("heading", { name: "Créer un compte" })).toBeVisible();
    await page.getByLabel("E-mail").fill(testEmail());
    await page.getByLabel("Mot de passe", { exact: true }).fill("short");
    await page.getByRole("button", { name: "Créer mon compte" }).click();
    await expect(page.getByText("Mot de passe trop court : 8 caractères minimum.")).toBeVisible();
  });

  test("the confirmation link activates the account, signs in and creates the profile", async ({ page }) => {
    const email = testEmail();
    await page.goto(await emailLink("signup", email));

    await expect(page).toHaveURL(/\/app$/);
    await expect(page.getByRole("button", { name: "Menu du profil" })).toContainText(email);

    const { data: profile } = await adminClient().from("profiles").select("email").eq("email", email).single();
    expect(profile?.email).toBe(email);
  });

  test("a confirmation link opened in another browser sends to the login page with a message", async ({ page }) => {
    await page.goto("/login?notice=confirmed");
    await expect(page.locator("main").getByRole("status")).toHaveText(
      "Votre adresse est confirmée. Connectez-vous pour accéder à votre espace.",
    );
  });

  test("a confirmation link can only be used once", async ({ page }) => {
    const link = await emailLink("signup", testEmail());
    await page.goto(link);
    await expect(page).toHaveURL(/\/app$/);
    await signOut(page);

    await page.goto(link);
    await expect(page).toHaveURL(/\/link-expired\?type=signup$/);
    await expect(page.getByRole("heading", { name: "Ce lien n'est plus valide" })).toBeVisible();
  });
});

test.describe("forgot password", () => {
  test("the form checks the address (without sending anything)", async ({ page }) => {
    await page.goto("/login");
    await page.getByRole("link", { name: "Mot de passe oublié ?" }).click();
    await expect(page.getByRole("heading", { name: "Mot de passe oublié" })).toBeVisible();
    await page.getByRole("button", { name: "Envoyer le lien" }).click();
    await expect(page.getByText("Indiquez votre adresse e-mail.")).toBeVisible();
  });

  test("the reset link leads to a new password, which then works", async ({ page }) => {
    const user = await createUser();
    await page.goto(await emailLink("recovery", user.email));

    await expect(page).toHaveURL(/\/reset-password$/);
    await expect(page.getByText(user.email)).toBeVisible();

    const newPassword = "new-e2e-password-456";
    await page.getByLabel("Nouveau mot de passe").fill(newPassword);
    await page.getByRole("button", { name: "Enregistrer et me connecter" }).click();
    await expect(page).toHaveURL(/\/app$/);

    await signOut(page);
    await login(page, user.email, TEST_PASSWORD);
    await expect(page.locator("main").getByRole("alert")).toHaveText("E-mail ou mot de passe incorrect.");
    await login(page, user.email, newPassword);
    await expect(page).toHaveURL(/\/app$/);
  });

  test("an invalid reset link opens the expired link page", async ({ page }) => {
    await page.goto("/auth/confirm?token_hash=not-a-real-token&type=recovery");
    await expect(page).toHaveURL(/\/link-expired\?type=recovery$/);
    await expect(page.getByRole("button", { name: "Recevoir un nouveau lien" })).toBeVisible();
  });

  test("the new password page needs the email link", async ({ page }) => {
    await page.goto("/reset-password");
    await expect(page).toHaveURL(/\/link-expired\?type=recovery$/);
  });
});
